// Complete annotated program:

#include <iostream>      // Include the I/O library
using namespace std;     // Use standard namespace (shortcut)

int main() {             // Program starts here

    // This line prints text to the screen
    cout << "Hello from C++!" << endl;

    // This line prints a number
    cout << "The answer is: " << 42 << endl;

    // This line prints multiple things
    cout << "Name: " << "Student" << ", Age: " << 20 << endl;

    return 0;            // Program ended successfully
}

#include <iostream>
using namespace std;

int main() {
    // Printing different types
    cout << "=== Printing Different Types ===" << endl;
    cout << "Text: Hello World" << endl;
    cout << "Number: " << 42 << endl;
    cout << "Decimal: " << 3.14 << endl;
    cout << "Mixed: " << "Age " << 25 << " years" << endl;

    cout << endl;

    // The conveyor belt analogy
    cout << "This " << "is " << "a " << "conveyor " << "belt!" << endl;

    return 0;
}

examples.code:
// This is a comment - the compiler ignores it
// Comments help humans understand the code

#include <iostream>  // Include Input/Output library
using namespace std; // Use standard namespace

int main() {         // Main function - program starts here

    // Print a greeting
    cout << "Welcome to C++!" << endl;

    // Print some numbers
    cout << "1 + 1 = " << 1 + 1 << endl;

    // Print multiple items
    cout << "C++" << " is " << "awesome!" << endl;

    return 0;        // Program finished successfully
}

#include <iostream>
using namespace std;

int main() {
    // This is a single-line comment
    cout << "Comments are invisible to the computer" << endl;

    /* This is a
       multi-line comment
       spanning several lines */
    cout << "Use comments to explain your code!" << endl;

    // You can also comment out code:
    // cout << "This won't print" << endl;

    cout << "Only this line prints!" << endl;

    return 0;
}

#include <iostream>
using namespace std;

int main() {
    // Method 1: Using endl
    cout << "Line 1" << endl;
    cout << "Line 2" << endl;

    // Method 2: Using \n (faster!)
    cout << "Line 3\n";
    cout << "Line 4\n";

    // Method 3: Multiple \n in one cout
    cout << "Line 5\nLine 6\nLine 7\n";

    return 0;
}

